package com.church.church_backend;

import java.util.*; import java.util.stream.Collectors;
import org.springframework.http.HttpStatus; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;

@RestController @RequestMapping("/api/priests")
public class PriestController {
 private final PriestRepository priests; private final DeaneryRepository deaneries; private final ParishRepository parishes;
 public PriestController(PriestRepository priests,DeaneryRepository deaneries,ParishRepository parishes){this.priests=priests;this.deaneries=deaneries;this.parishes=parishes;}
 @GetMapping public List<Map<String,Object>> list(@RequestParam(name="deanery_id",required=false) Long deaneryId,@RequestParam(name="parish_id",required=false) Long parishId,@RequestParam(name="search",required=false) String search){List<Priest> rows=parishId!=null?priests.findByParishId(parishId):deaneryId!=null?priests.findByDeaneryId(deaneryId):priests.findAll();if(search!=null&&!search.isBlank()){String q=search.trim().toLowerCase(Locale.ROOT);rows=rows.stream().filter(p->p.getName()!=null&&p.getName().toLowerCase(Locale.ROOT).contains(q)).collect(Collectors.toList());}return rows.stream().map(this::dto).collect(Collectors.toList());}
 @GetMapping("/{id}") public ResponseEntity<?> get(@PathVariable Long id){return priests.findById(id).<ResponseEntity<?>>map(p->ResponseEntity.ok(dto(p))).orElseGet(()->error(HttpStatus.NOT_FOUND,"Priest not found"));}
 @PostMapping public ResponseEntity<?> create(@RequestBody Priest in){if(blank(in.getName()))return error(HttpStatus.BAD_REQUEST,"Priest name is required");if(in.getDeaneryId()!=null&&!deaneries.existsById(in.getDeaneryId()))return error(HttpStatus.BAD_REQUEST,"Deanery not found");if(in.getParishId()!=null&&!parishes.existsById(in.getParishId()))return error(HttpStatus.BAD_REQUEST,"Parish not found");in.setId(null);return ResponseEntity.status(HttpStatus.CREATED).body(dto(priests.save(in)));}
 @PutMapping("/{id}") public ResponseEntity<?> update(@PathVariable Long id,@RequestBody Priest in){Optional<Priest> f=priests.findById(id);if(f.isEmpty())return error(HttpStatus.NOT_FOUND,"Priest not found");if(in.getDeaneryId()!=null&&!deaneries.existsById(in.getDeaneryId()))return error(HttpStatus.BAD_REQUEST,"Deanery not found");if(in.getParishId()!=null&&!parishes.existsById(in.getParishId()))return error(HttpStatus.BAD_REQUEST,"Parish not found");Priest p=f.get();if(in.getName()!=null)p.setName(in.getName());if(in.getTitle()!=null)p.setTitle(in.getTitle());if(in.getPhotoUrl()!=null)p.setPhotoUrl(in.getPhotoUrl());if(in.getRole()!=null)p.setRole(in.getRole());if(in.getDeaneryId()!=null)p.setDeaneryId(in.getDeaneryId());if(in.getParishId()!=null)p.setParishId(in.getParishId());if(in.getPhone()!=null)p.setPhone(in.getPhone());if(in.getEmail()!=null)p.setEmail(in.getEmail());if(in.getBio()!=null)p.setBio(in.getBio());return ResponseEntity.ok(dto(priests.save(p)));}
 @DeleteMapping("/{id}") public ResponseEntity<?> delete(@PathVariable Long id){Optional<Priest> f=priests.findById(id);if(f.isEmpty())return error(HttpStatus.NOT_FOUND,"Priest not found");Priest p=f.get();for(Deanery d:deaneries.findAll()){boolean changed=false;if(Objects.equals(d.getDeanId(),id)){d.setDeanId(null);changed=true;}if(Objects.equals(d.getViceDeanId(),id)){d.setViceDeanId(null);changed=true;}if(changed)deaneries.save(d);}for(Parish parish:parishes.findAll()){boolean changed=false;if(Objects.equals(parish.getParishPriestId(),id)){parish.setParishPriestId(null);changed=true;}if(Objects.equals(parish.getAssistantPriestId(),id)){parish.setAssistantPriestId(null);changed=true;}if(changed)parishes.save(parish);}priests.delete(p);return ResponseEntity.ok(Map.of("message","Priest deleted","id",id));}
 private boolean blank(String s){return s==null||s.trim().isEmpty();}private ResponseEntity<Map<String,String>> error(HttpStatus s,String m){return ResponseEntity.status(s).body(Map.of("error",m));}
 private Map<String,Object> dto(Priest p){Map<String,Object> m=new LinkedHashMap<>();m.put("id",p.getId());m.put("name",p.getName());m.put("title",p.getTitle());m.put("photoUrl",p.getPhotoUrl());m.put("role",p.getRole());m.put("deaneryId",p.getDeaneryId());m.put("parishId",p.getParishId());m.put("phone",p.getPhone());m.put("email",p.getEmail());m.put("bio",p.getBio());return m;}
}
